}

/* ===== Layout ===== */
.page-header {
  text-align: center;
  margin-bottom: 2.5rem;
  max-width: 36rem;
  width: 100%;
}

.page-header h1 {
  font-size: clamp(1.5rem, 4vw, 2rem);
  font-weight: 700;
  color: #f8fafc;
  letter-spacing: -0.02em;
  margin-bottom: 0.5rem;
}

.page-header p {
  color: #94a3b8;
  font-size: 0.9375rem;
}

/* ===== Card ===== */
.card {
  background: #1e2130;
  border: 1px solid #2d3348;
  border-radius: 1rem;
  padding: clamp(1.5rem, 5vw, 2.5rem);
  width: 100%;
  max-width: 36rem;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

/* ===== Required legend ===== */
.required-legend {
  font-size: 0.8125rem;
  color: #94a3b8;
  margin-bottom: 1.5rem;
}

.required-legend .req-star {
  color: #f87171;
  font-weight: 700;
  margin-right: 0.2rem;
}

/* ===== Form fields ===== */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  margin-bottom: 1.25rem;
}

.form-field label {
  font-size: 0.9375rem;
  font-weight: 500;
  color: #cbd5e1;
}

.form-field label .req-star {
  color: #f87171;
  font-weight: 700;
  margin-left: 0.15rem;
}

.form-field input {
  background: #131621;
  border: 1.5px solid #3b4261;
  border-radius: 0.5rem;
  color: #f1f5f9;
  font-size: 1rem;
  font-family: inherit;
  padding: 0.625rem 0.875rem;
  transition: border-color 0.15s, box-shadow 0.15s;
  width: 100%;
  appearance: none;
  -webkit-appearance: none;
}

.form-field input::placeholder {
  color: #4b5563;
}

.form-field input:hover {
  border-color: #5b6490;
}

.form-field input:focus {
  outline: none;
  border-color: #7c6af7;
  box-shadow: 0 0 0 3px rgba(124, 106, 247, 0.35);
}

/* ===== Invalid state (only shown after submit attempt) ===== */
.form-field input[aria-invalid="true"] {
  border-color: #f87171;
}

.form-field input[aria-invalid="true"]:focus {
  border-color: #f87171;
  box-shadow: 0 0 0 3px rgba(248, 113, 113, 0.3);
}

/* ===== Helper text ===== */
.field-help {
  font-size: 0.8125rem;
  color: #64748b;
}

/* ===== Error text ===== */
.field-error {
  font-size: 0.8125rem;
  color: #fca5a5;
  display: none;
}

.field-error.visible {
  display: block;
}

/* ===== Status region ===== */
.form-status {
  font-size: 0.9375rem;
  border-radius: 0.5rem;
  padding: 0.75rem 1rem;
  margin-bottom: 1.25rem;
  display: none;
}

.form-status.success {
  display: block;
  background: rgba(52, 211, 153, 0.1);
  border: 1px solid #34d399;
  color: #6ee7b7;
}

.form-status.error-summary {
  display: block;
  background: rgba(248, 113, 113, 0.1);
  border: 1px solid #f87171;
  color: #fca5a5;
}

/* ===== Submit button ===== */
.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 0.5rem;
  width: 100%;
  padding: 0.75rem 1.5rem;
  background: linear-gradient(135deg, #7c6af7 0%, #5e50e0 100%);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  border: none;
  border-radius: 0.5rem;
  cursor: pointer;
  transition: opacity 0.15s, box-shadow 0.15s, transform 0.1s;
  letter-spacing: 0.01em;
}

.btn-submit:hover {
  opacity: 0.92;
  box-shadow: 0 4px 16px rgba(124, 106, 247, 0.45);
}

.btn-submit:active {
  transform: translateY(1px);
}

.btn-submit:focus-visible {
  outline: 3px solid #a78bfa;
  outline-offset: 3px;
}

/* ===== Reflow: narrow viewport ===== */
@media (max-width: 360px) {
  .card {
    border-radius: 0.75rem;
    padding: 1.25rem;
  }

  .page-header h1 {
    font-size: 1.375rem;
  }
}

/* ===== Reduced motion ===== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }

  html {
    scroll-behavior: auto;
  }
}
